290	    /** 查询窗口当前可用容量。 */
291	    public CapacityResponse getCapacity(long windowId) {
292	        WindowRow window = repository.findWindowById(windowId);
293	        if (window == null) {
294	            throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
295	        }
296	        CurtailmentRow active = repository.findActiveCurtailment(windowId);
297	        BigDecimal available = active != null ? active.volume() : window.plannedVolume();
298	        BigDecimal approved = repository.sumApprovedAmount(windowId);
299	        return new CapacityResponse(window.id(), fmt(window.plannedVolume()),
300	                active != null ? fmt(active.volume()) : null, fmt(available), fmt(approved),
301	                fmt(available.subtract(approved)));
302	    }
303	
304	    /** 查询窗口历史明细：窗口 + 全部申请 + 全部限供。 */
305	    public HistoryResponse getHistory(long windowId) {
306	        WindowRow window = repository.findWindowById(windowId);
307	        if (window == null) {
308	            throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + windowId);
309	        }
310	        CurtailmentRow active = repository.findActiveCurtailment(windowId);
311	        List<AllocationResponse> allocations = repository.listAllocations(windowId).stream()
312	                .map(this::toAllocationResponse).toList();
313	        List<CurtailmentResponse> curtailments = repository.listCurtailments(windowId).stream()
314	                .map(this::toCurtailmentResponse).toList();
315	        return new HistoryResponse(toWindowResponse(window, active), allocations, curtailments);
316	    }
317	
318	    // ------------------------------------------------------------------
319	    // 幂等命令框架
320	    // ------------------------------------------------------------------
321	
322	    /**
323	     * 在单事务内执行幂等命令：先占位插入命令行，再执行业务并写回响应。
324	     * 并发同键时占位插入会因唯一约束失败，随后读取已提交的首次结果重放或报 409。
325	     */
326	    private <T> T runCommand(String operation, String commandKey, String params, Class<T> type,
327	                             Supplier<T> business) {
328	        try {
329	            return tx.execute(status -> {
330	                CommandRow existing = repository.findCommand(commandKey);
331	                if (existing != null) {
332	                    return replay(existing, operation, params, type);
333	                }
334	                repository.insertCommand(commandKey, operation, params, nowNanos());
335	                T result = business.get();
336	                repository.updateCommandResponse(commandKey, toJson(result));
337	                return result;
338	            });
339	        } catch (DuplicateKeyException e) {
340	            CommandRow committed = repository.findCommand(commandKey);
341	            if (committed == null || committed.response() == null) {
342	                throw ApiException.conflict("COMMAND_CONFLICT", "相同 commandKey 的命令正在处理，请重试");
343	            }
344	            return replay(committed, operation, params, type);
345	        }
346	    }
347	
348	    private <T> T replay(CommandRow existing, String operation, String params, Class<T> type) {
349	        if (!existing.operation().equals(operation) || !existing.params().equals(params)) {
350	            throw ApiException.conflict("COMMAND_KEY_REUSED", "相同 commandKey 但参数不同，拒绝重放");
351	        }
352	        return fromJson(existing.response(), type);
353	    }
354	
355	    // ------------------------------------------------------------------
356	    // 内部工具
357	    // ------------------------------------------------------------------
358	
359	    private WindowRow lockWindowOf(AllocationRow allocation) {
360	        WindowRow window = repository.lockWindowById(allocation.windowId());
361	        if (window == null) {
362	            throw ApiException.notFound("WINDOW_NOT_FOUND", "供水窗口不存在: " + allocation.windowId());
363	        }
364	        return window;
365	    }
366	
367	    private BigDecimal availableTotal(WindowRow window) {
368	        CurtailmentRow active = repository.findActiveCurtailment(window.id());
369	        return active != null ? active.volume() : window.plannedVolume();
370	    }
371	
372	    private WindowResponse toWindowResponse(WindowRow row, CurtailmentRow active) {
373	        BigDecimal available = active != null ? active.volume() : row.plannedVolume();
374	        return new WindowResponse(row.id(), row.windowKey(), row.channelId(), toIso(row.startNanos()),
375	                toIso(row.endNanos()), fmt(row.plannedVolume()),
376	                active != null ? fmt(active.volume()) : null, fmt(available), toIso(row.createdNanos()));
377	    }
378	
379	    private AllocationResponse toAllocationResponse(AllocationRow row) {
380	        return new AllocationResponse(row.allocationKey(), row.windowId(), row.userId(), fmt(row.amount()),
381	                fmt(row.heldAmount()), row.requester(), row.status(),
382	                toIso(row.createdNanos()), toIso(row.updatedNanos()));
383	    }
384	
385	    private TransferResponse toTransferResponse(TransferRow row) {
386	        return new TransferResponse(row.transferKey(), row.windowId(), row.sourceAllocationKey(),
387	                row.targetAllocationKey(), fmt(row.amount()), row.actor(), toIso(row.createdNanos()));
388	    }
389	
390	    private CurtailmentResponse toCurtailmentResponse(CurtailmentRow row) {
391	        return new CurtailmentResponse(row.id(), row.windowId(), fmt(row.volume()), row.status(),
392	                toIso(row.createdNanos()), row.cancelledNanos() == null ? null : toIso(row.cancelledNanos()));
393	    }
394	
395	    static long nowNanos() {
396	        return toNanos(Instant.now());
397	    }
398	
399	    /** Instant -> UTC 纳秒时间戳。 */
400	    static long toNanos(Instant instant) {
401	        return Math.addExact(Math.multiplyExact(instant.getEpochSecond(), NANOS_PER_SECOND), instant.getNano());
402	    }
403	
404	    /** UTC 纳秒时间戳 -> Instant。 */
405	    static Instant toInstant(long nanos) {
406	        return Instant.ofEpochSecond(Math.floorDiv(nanos, NANOS_PER_SECOND),
407	                Math.floorMod(nanos, NANOS_PER_SECOND));
408	    }
409	
410	    static String toIso(long nanos) {
411	        return toInstant(nanos).toString();
412	    }
413	
414	    static long parseInstant(String field, String value) {
415	        if (value == null || value.isBlank()) {
416	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 不能为空");
417	        }
418	        try {
419	            return toNanos(Instant.parse(value.trim()));
420	        } catch (DateTimeParseException | ArithmeticException e) {
421	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 不是合法的 UTC 时刻: " + value);
422	        }
423	    }
424	
425	    /** 解析水量：十进制字符串，大于 0，最多 3 位小数。 */
426	    static BigDecimal parseAmount(String field, String value) {
427	        if (value == null || value.isBlank()) {
428	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 不能为空");
429	        }
430	        String trimmed = value.trim();
431	        if (!AMOUNT_PATTERN.matcher(trimmed).matches()) {
432	            throw ApiException.badRequest("INVALID_ARGUMENT",
433	                    field + " 必须为大于 0 的十进制字符串，最多 3 位小数: " + value);
434	        }
435	        BigDecimal amount = new BigDecimal(trimmed);
436	        if (amount.signum() <= 0) {
437	            throw ApiException.badRequest("INVALID_ARGUMENT", field + " 必须大于 0");
438	        }
439	        return amount;
440	    }
441	
442	    static void requireKey(String field, String value) {
443	        if (value == null || !KEY_PATTERN.matcher(value).matches()) {
444	            throw ApiException.badRequest("INVALID_ARGUMENT",
445	                    field + " 不能为空，且仅允许字母数字及 . - _ :，最长 128 字符");
446	        }
447	    }
448	
449	    /** 水量格式化为十进制字符串（去掉多余尾零）。 */
450	    static String fmt(BigDecimal value) {
451	        BigDecimal stripped = value.stripTrailingZeros();
452	        if (stripped.signum() == 0) {
453	            return "0";
454	        }
455	        return stripped.toPlainString();
456	    }
457	
458	    private String toJson(Object value) {
459	        try {
460	            return objectMapper.writeValueAsString(value);
461	        } catch (Exception e) {
462	            throw new IllegalStateException("响应序列化失败", e);
463	        }
464	    }
465	
466	    private <T> T fromJson(String json, Class<T> type) {
467	        try {
468	            return objectMapper.readValue(json, type);
469	        } catch (Exception e) {
470	            throw new IllegalStateException("响应反序列化失败", e);
471	        }
472	    }
473	}
