455	        String approved = submitAllocation(windowId, "user-1", "6", "alice");
456	        approve(approved, 200);
457	        String pending = submitAllocation(windowId, "user-2", "4", "bob");
458	
459	        ExecutorService pool = Executors.newFixedThreadPool(2);
460	        CountDownLatch gate = new CountDownLatch(1);
461	        String approveCommand = key("ap");
462	        String curtailCommand = key("cu");
463	        Future<Integer> approveFuture = pool.submit(() -> {
464	            gate.await();
465	            try {
466	                waterService.approveAllocation(approveCommand, pending);
467	                return 200;
468	            } catch (ApiException e) {
469	                return e.status().value();
470	            }
471	        });
472	        Future<Integer> curtailFuture = pool.submit(() -> {
473	            gate.await();
474	            try {
475	                waterService.createCurtailment(curtailCommand, windowId, "8");
476	                return 200;
477	            } catch (ApiException e) {
478	                return e.status().value();
479	            }
480	        });
481	        gate.countDown();
482	        int approveStatus = approveFuture.get(30, TimeUnit.SECONDS);
483	        int curtailStatus = curtailFuture.get(30, TimeUnit.SECONDS);
484	        pool.shutdown();
485	
486	        // 按事务提交顺序：恰好一个成功（先批准 6+4=10 则限供 8 冲突；先限供 8 则批准 10 超额）
487	        assertTrue((approveStatus == 200) != (curtailStatus == 200),
488	                "approve=" + approveStatus + " curtail=" + curtailStatus);
489	        if (approveStatus == 200) {
490	            assertEquals(409, curtailStatus);
491	            assertEquals("10", capacity(windowId).get("approvedTotal").asText());
492	        } else {
493	            assertEquals(422, approveStatus);
494	            assertEquals("8", capacity(windowId).get("availableTotal").asText());
495	        }
496	        // 不变式：已批准总量永不超过最终可用总量
497	        JsonNode cap = capacity(windowId);
498	        assertTrue(Double.parseDouble(cap.get("approvedTotal").asText())
499	                <= Double.parseDouble(cap.get("availableTotal").asText()));
500	    }
